export default async function POST(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  const { id } = params
  const book = await db.book.findUnique({ where: { id } })
  if (!book) return NextResponse.json({ error: 'not found' }, { status: 404 })
  const body = await req.json()
  const { name, category, sku, quantity, minQuantity } = body
  if (name == null || category == null || sku == null) {
    return NextResponse.json({ error: 'missing required field' }, { status: 400 })
  }
  if (quantity == null) quantity = 0
  if (minQuantity == null) minQuantity = 0
  if (quantity < minQuantity) {
    return NextResponse.json({
      error: `quantity must be at least ${minQuantity}`,
    }, { status: 400 })
  }
  const updated = await db.book.update({ where: { id }, data: { name, category, sku, quantity } })
  return NextResponse.json({ item: updated }, { status: 200 })
}

